import crypto from 'node:crypto';
import type { Context } from 'hono';
import type { AppEnvironment } from '@/app';
import type {
    NewSitePackageRevisionInput,
    SitePackageRevisionRecord,
    SitePackageRuntimeMode
} from '@/ports/repositories';
import type { UploadedFile } from '@/ports/http';
import type { ObjectStorage } from '@/ports/object-storage';
import {
    parseSitePackageArchive,
    SITE_PACKAGE_ARCHIVE_LIMITS,
    type SitePackageArchiveManifest
} from '@/domains/site-packages/package-archive';
import { randomHex } from '@/utils/crypto/random';
import { sha256Hex } from '@/utils/crypto/sha256';

const UUID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const SLUG_PATTERN = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;
const STORED_MANIFEST_SCHEMA_VERSION = 1;
const SITE_ICON_FILE_PATH = /\.(?:avif|bmp|gif|ico|jpe?g|jfif|png|svg|webp)$/i;
const LEGACY_SITE_ICON_PATH = /(?:^|\/)favicon\.(?:avif|bmp|gif|ico|jpe?g|jfif|png|svg|webp)$/i;

export interface SitePackageManifest {
    readonly entries: ReadonlyMap<string, string>;
    readonly iconPath: string | null;
}

export interface StoredSitePackageRevision {
    revision: NewSitePackageRevisionInput;
    prefix: string;
    previewToken: string;
    storedKeys: readonly string[];
    warnings: readonly string[];
    hasScripts: boolean;
}

export function sitePackageUuid(value: unknown, label = 'ID'): string {
    const id = String(value || '').trim();
    if (!UUID_PATTERN.test(id)) {
        throw Object.assign(new Error(`${label}无效`), { status: 400 });
    }
    return id.toLowerCase();
}

export function sitePackageSlug(value: unknown): string {
    const slug = String(value || '').trim();
    if (!SLUG_PATTERN.test(slug) || slug.length > 80) {
        throw Object.assign(new Error('slug 必须为小写字母、数字和单连字符'), { status: 400 });
    }
    return slug;
}

export function sitePackageTitle(value: unknown): string {
    const title = String(value || '').trim();
    if (!title || title.length > 200) {
        throw Object.assign(new Error('标题不能为空且不能超过 200 个字符'), { status: 400 });
    }
    return title;
}

export function sitePackageDescription(value: unknown): string {
    const description = String(value || '').trim();
    if (description.length > 4_000) {
        throw Object.assign(new Error('简介不能超过 4000 个字符'), { status: 400 });
    }
    return description;
}

export function sitePackageRuntimeMode(value: unknown): SitePackageRuntimeMode {
    if (value !== 'safe' && value !== 'isolated-script') {
        throw Object.assign(new Error('runtimeMode 必须为 safe 或 isolated-script'), {
            status: 400
        });
    }
    return value;
}

export function oneArchiveFile(
    value: UploadedFile | UploadedFile[] | undefined
): UploadedFile {
    const file = Array.isArray(value) ? value[0] : value;
    if (!file || Array.isArray(value) && value.length !== 1) {
        throw Object.assign(new Error('必须上传一个 ZIP archive 文件'), { status: 400 });
    }
    return file;
}

export async function parseUploadedSitePackage(
    file: UploadedFile,
    entryPath: string,
    runtimeMode: SitePackageRuntimeMode
): Promise<SitePackageArchiveManifest> {
    if (file.body.byteLength > SITE_PACKAGE_ARCHIVE_LIMITS.archiveBytes) {
        throw Object.assign(new Error('站点包超过 80 MiB 限制'), { status: 413 });
    }
    const parsed = await parseSitePackageArchive(file.body, { entryPath, runtimeMode });
    if (parsed.entryPath.includes('/')) {
        throw Object.assign(new Error('entryPath 必须是 ZIP 根目录中的 HTML 文件'), {
            status: 400
        });
    }
    return parsed;
}

export async function storeSitePackageRevision(
    storage: ObjectStorage,
    packageId: string,
    revisionId: string,
    createdBy: number,
    createdAt: number,
    archive: UploadedFile,
    parsed: SitePackageArchiveManifest,
    cleanup: (key: string) => Promise<void> = (key) => storage.delete(key)
): Promise<StoredSitePackageRevision> {
    const prefix = `site-packages/${packageId}/revisions/${revisionId}`;
    const sourceKey = `${prefix}/source.zip`;
    const manifestKey = `${prefix}/manifest.json`;
    const entries = Object.fromEntries(parsed.entries.map((entry) => [
        entry.path,
        `${prefix}/files/${entry.path}`
    ]));
    const manifestJson = JSON.stringify({
        schemaVersion: STORED_MANIFEST_SCHEMA_VERSION,
        iconPath: parsed.iconPath,
        entries
    });
    const storedKeys: string[] = [];
    const previewToken = randomHex(32);
    const previewTokenHash = await sha256Hex(new TextEncoder().encode(previewToken));
    try {
        for (const entry of parsed.entries) {
            await storage.put(entries[entry.path], entry.body, {
                contentType: entry.contentType,
                sha256: entry.sha256,
                metadata: { packageId, revisionId, immutable: 'true' }
            });
            storedKeys.push(entries[entry.path]);
        }
        await storage.put(sourceKey, archive.body, {
            contentType: 'application/zip',
            sha256: parsed.archiveSha256,
            metadata: { packageId, revisionId, internal: 'source' }
        });
        storedKeys.push(sourceKey);
        const manifestBody = new TextEncoder().encode(manifestJson);
        await storage.put(manifestKey, manifestBody, {
            contentType: 'application/json; charset=utf-8',
            sha256: await sha256Hex(manifestBody),
            metadata: { packageId, revisionId, internal: 'manifest' }
        });
        storedKeys.push(manifestKey);
    } catch (error) {
        await Promise.allSettled(storedKeys.map((key) => cleanup(key)));
        throw error;
    }
    return {
        prefix,
        previewToken,
        storedKeys,
        warnings: parsed.warnings,
        hasScripts: parsed.hasScripts,
        revision: {
            id: revisionId,
            packageId,
            entryPath: parsed.entryPath,
            runtimeMode: parsed.runtimeMode,
            state: 'ready',
            fileCount: parsed.fileCount,
            totalBytes: parsed.totalUncompressedSize,
            sourceKey,
            sourceSha256: parsed.archiveSha256,
            manifestKey,
            manifestJson,
            previewTokenHash,
            createdBy,
            createdAt
        }
    };
}

function singleForwardedValue(value: string | null): string | undefined {
    const normalized = value?.trim();
    return normalized && !normalized.includes(',') ? normalized : undefined;
}

export function sitePackageRequestOrigin(
    request: Request,
    source: 'direct' | 'nginx'
): string {
    const requestOrigin = new URL(request.url).origin;
    if (source !== 'nginx') return requestOrigin;
    const protocol = singleForwardedValue(request.headers.get('x-forwarded-proto'))
        ?.toLowerCase();
    const host = singleForwardedValue(request.headers.get('x-forwarded-host'));
    if (!protocol || !host || !['http', 'https'].includes(protocol)) return requestOrigin;
    let forwarded: URL;
    try {
        forwarded = new URL(`${protocol}://${host}`);
    } catch {
        return requestOrigin;
    }
    if (
        forwarded.protocol !== `${protocol}:` || forwarded.username || forwarded.password ||
        forwarded.pathname !== '/' || forwarded.search || forwarded.hash
    ) {
        return requestOrigin;
    }
    const port = singleForwardedValue(request.headers.get('x-forwarded-port'));
    if (port !== undefined) {
        const parsedPort = Number(port);
        if (!/^\d+$/.test(port) || parsedPort < 1 || parsedPort > 65_535) {
            return requestOrigin;
        }
        forwarded.port = port;
    }
    return forwarded.origin;
}

export function mainSiteOrigin(c: Context<AppEnvironment>): string {
    const source = c.get('services').config?.clientAddressSource || 'direct';
    return sitePackageRequestOrigin(c.req.raw, source);
}

export function sitePackageManifest(revision: SitePackageRevisionRecord): SitePackageManifest {
    let candidate: unknown;
    try {
        candidate = JSON.parse(revision.manifest_json);
    } catch {
        throw new Error('Stored site-package manifest is invalid');
    }
    if (!candidate || typeof candidate !== 'object' || Array.isArray(candidate)) {
        throw new Error('Stored site-package manifest is invalid');
    }
    const record = candidate as Record<string, unknown>;
    const versioned = record.schemaVersion === STORED_MANIFEST_SCHEMA_VERSION;
    const rawEntries = versioned ? record.entries : record;
    if (!rawEntries || typeof rawEntries !== 'object' || Array.isArray(rawEntries)) {
        throw new Error('Stored site-package manifest is invalid');
    }
    const entries = new Map<string, string>();
    for (const [path, key] of Object.entries(rawEntries)) {
        if (typeof key !== 'string') throw new Error('Stored site-package manifest is invalid');
        entries.set(path, key);
    }
    if (entries.size !== revision.file_count) {
        throw new Error('Stored site-package manifest file count differs');
    }
    let iconPath: string | null;
    if (versioned) {
        const candidateIconPath = record.iconPath;
        if (candidateIconPath !== null && typeof candidateIconPath !== 'string') {
            throw new Error('Stored site-package manifest icon path is invalid');
        }
        iconPath = candidateIconPath;
        if (iconPath && (!entries.has(iconPath) || !SITE_ICON_FILE_PATH.test(iconPath))) {
            throw new Error('Stored site-package manifest icon path is invalid');
        }
    } else {
        iconPath = Array.from(entries.keys())
            .filter((path) => LEGACY_SITE_ICON_PATH.test(path))
            .sort((left, right) => {
                const leftRoot = left.includes('/') ? 1 : 0;
                const rightRoot = right.includes('/') ? 1 : 0;
                return leftRoot - rightRoot || left.localeCompare(right);
            })[0] ?? null;
    }
    return { entries, iconPath };
}

export function manifestEntries(revision: SitePackageRevisionRecord): Map<string, string> {
    return new Map(sitePackageManifest(revision).entries);
}

function decodeAssetSegment(value: string): string | null {
    let decoded: string;
    try {
        decoded = decodeURIComponent(value);
    } catch {
        return null;
    }
    if (
        !decoded || decoded === '.' || decoded === '..' ||
        /[/\\\u0000-\u001f\u007f]/.test(decoded) || /%[0-9a-f]{2}/i.test(decoded)
    ) {
        return null;
    }
    return decoded;
}

export function requestedPackageAssetPath(
    request: Request,
    routeSegments: readonly string[],
    entryPath: string
): string | null {
    const raw = new URL(request.url).pathname.split('/');
    if (raw.shift() !== '') return null;
    if (raw.length < routeSegments.length) return null;
    for (let index = 0; index < routeSegments.length; index += 1) {
        const decoded = decodeAssetSegment(raw[index]);
        if (decoded !== routeSegments[index]) return null;
    }
    const remainder = raw.slice(routeSegments.length);
    if (remainder.length === 1 && remainder[0] === '') return entryPath;
    if (!remainder.length) return entryPath;
    if (remainder.some((segment) => segment === '')) return null;
    const decoded = remainder.map(decodeAssetSegment);
    return decoded.every((segment): segment is string => segment !== null)
        ? decoded.join('/')
        : null;
}

export function sitePackageContentCsp(
    runtimeMode: SitePackageRuntimeMode,
    frameAncestor: string | readonly string[],
    contentSource: string,
    directAssetOrigin?: string
): string {
    const frameAncestors = typeof frameAncestor === 'string'
        ? frameAncestor
        : frameAncestor.join(' ');
    const scripts = runtimeMode === 'isolated-script'
        ? `script-src ${contentSource} 'unsafe-inline'; sandbox allow-scripts`
        : "script-src 'none'; sandbox";
    const assetSources = directAssetOrigin
        ? `${contentSource} data: ${directAssetOrigin}`
        : `${contentSource} data:`;
    return [
        "default-src 'none'",
        "base-uri 'none'",
        "connect-src 'none'",
        `font-src ${assetSources}`,
        "form-action 'none'",
        "frame-src 'none'",
        `frame-ancestors ${frameAncestors}`,
        `img-src ${assetSources}`,
        `media-src ${assetSources}`,
        "object-src 'none'",
        scripts,
        `style-src ${contentSource} 'unsafe-inline'`,
        "worker-src 'none'"
    ].join('; ');
}

export function sitePackageFrameAncestorOrigins(siteOrigin: string): readonly string[] {
    const parsed = new URL(siteOrigin);
    const hostname = parsed.hostname.replace(/^\[|\]$/g, '');
    if (!['127.0.0.1', '::1', 'localhost'].includes(hostname)) return [parsed.origin];
    const suffix = parsed.port ? `:${parsed.port}` : '';
    return [
        `${parsed.protocol}//127.0.0.1${suffix}`,
        `${parsed.protocol}//localhost${suffix}`,
        `${parsed.protocol}//[::1]${suffix}`
    ];
}

export function newSitePackageId(): string {
    return crypto.randomUUID();
}
